                // Canvas rows run downwards; tangent V runs upwards.
                ny = (height(x, y + 1) - height(x, y - 1)) * size * 0.5 * strength;
                nz = 1;
            } else {
                nx = (source[i] / 255 * 2 - 1) * strength;
