            result[i] = (nx / length * 0.5 + 0.5) * 255;
            result[i + 1] = (ny / length * 0.5 + 0.5) * 255;
            result[i + 2] = (nz / length * 0.5 + 0.5) * 255;
            result[i + 3] = 255;
        }
        return result;
    }
    nodes.evaluate = function (graph, size, time, context, target, targetPort = "out") {
        size = Math.max(1, Math.min(2048, Math.round(size) || 128));
        graph = nodes.parse(graph);
        var outputs = {};
        var cache = Object.create(null);
        var nodeMap = Object.create(null);
        for (var i = 0; i < graph.nodes.length; i++) {
            nodeMap[graph.nodes[i].id] = graph.nodes[i];
        }

        function inputBuffer(nodeId, port, stack) {
            var link = nodes.findLink(graph, nodeId, port);
            if (link) {
                return evaluateNode(link.from, stack, link.fromPort);
            }
            return null;
        }

        function evaluateNode(id, stack, port = "out") {
            if (cache[id]?.[port] !== undefined) return cache[id][port];
            if (stack.indexOf(id) >= 0) return null;
            var node = nodeMap[id];
            if (!node) return null;
            var definition = TYPES[node.type];
            if (!definition) return null;
            stack.push(id);
            var inputs = {};
            for (var i = 0; i < definition.inputs.length; i++) {
                var input = definition.inputs[i];
                inputs[input.key] = inputBuffer(id, input.key, stack);
            }
