    material.threeObj.transparent !== transparent ||
    material.threeObj.blending !== nextBlending ||
    material.threeObj.side !== nextSide ||
    material.threeObj.alphaTest !== alphaTest;

  material.threeObj.transparent = transparent;
  material.threeObj.blending = nextBlending;
  material.threeObj.side = nextSide;
  material.threeObj.alphaTest = alphaTest;
  if (needsUpdate) material.threeObj.needsUpdate = true;
