"use strict";

// Shared surface shader chunks and gradient canvas helpers: the GLSL
// string tables the PBR onBeforeCompile assembly stitches together,
// plus the seeded random and color-ramp painters for baked textures.

module.exports = function createSurfaceShader(THREE, document) {
const WRAP_VALUES = [
    THREE.ClampToEdgeWrapping,
    THREE.RepeatWrapping,
    THREE.MirroredRepeatWrapping,
];

const PZ_RAMP_SOURCE = "luminance;u;v";
const PZ_RAMP_INTERPOLATION = "linear;constant;ease";

const PZ_VERTEX_HEADER = [
    "uniform vec2 uPzRepeat;",
    "uniform vec2 uPzOffset;",
    "uniform vec2 uPzCenter;",
    "uniform float uPzRotation;",
    "uniform vec3 uPzProjRotation;",
    "uniform vec3 uPzProjScale;",
    "uniform vec3 uPzProjTranslate;",
    "vec3 pzRotateXYZ( vec3 p, vec3 r ) {",
    "    float cx = cos( r.x );",
    "    float sx = sin( r.x );",
    "    float cy = cos( r.y );",
    "    float sy = sin( r.y );",
    "    float cz = cos( r.z );",
    "    float sz = sin( r.z );",
    "    vec3 q = vec3( p.x, cx * p.y - sx * p.z, sx * p.y + cx * p.z );",
    "    q = vec3( cy * q.x + sy * q.z, q.y, -sy * q.x + cy * q.z );",
    "    return vec3( cz * q.x - sz * q.y, sz * q.x + cz * q.y, q.z );",
    "}",
].join("\n");

const PZ_UV_PROJECTION_CODE = [
    "#include <begin_vertex>",
    "vec3 pzProjected = transformed * uPzProjScale + uPzProjTranslate;",
    "pzProjected = pzRotateXYZ( pzProjected, uPzProjRotation );",
    "vec2 pzBaseUv = uv;",
    "#if PZ_PROJECTION == 1",
    "float pzRadius = max( length( pzProjected ), 0.0001 );",
    "pzBaseUv = vec2( atan( pzProjected.x, pzProjected.z ) * 0.15915494 + 0.5, asin( clamp( pzProjected.y / pzRadius, -1.0, 1.0 ) ) * 0.31830989 + 0.5 );",
    "#elif PZ_PROJECTION == 2",
    "pzBaseUv = vec2( atan( pzProjected.x, pzProjected.z ) * 0.15915494 + 0.5, pzProjected.y * 0.5 + 0.5 );",
    "#elif PZ_PROJECTION == 3",
    "vec3 pzAbsNormal = abs( normalize( objectNormal ) );",
    "if ( pzAbsNormal.x >= pzAbsNormal.y && pzAbsNormal.x >= pzAbsNormal.z ) {",
    "    pzBaseUv = vec2( pzProjected.z, pzProjected.y );",
    "} else if ( pzAbsNormal.y >= pzAbsNormal.z ) {",
    "    pzBaseUv = vec2( pzProjected.x, pzProjected.z );",
    "} else {",
    "    pzBaseUv = vec2( pzProjected.x, pzProjected.y );",
    "}",
    "#endif",
    "vec2 pzUv = pzBaseUv - uPzCenter;",
    "float pzCos = cos( uPzRotation );",
    "float pzSin = sin( uPzRotation );",
    "vPzUv = vec2( uPzRepeat.x * ( pzCos * pzUv.x + pzSin * pzUv.y ), uPzRepeat.y * ( -pzSin * pzUv.x + pzCos * pzUv.y ) ) + uPzCenter + uPzOffset;",
    "#if defined( USE_MAP ) || defined( USE_BUMPMAP ) || defined( USE_NORMALMAP ) || defined( USE_EMISSIVEMAP ) || defined( USE_ALPHAMAP ) || defined( USE_ROUGHNESSMAP ) || defined( USE_METALNESSMAP ) || defined( USE_SPECULARMAP )",
    "vUv = vPzUv;",
    "#endif",
].join("\n");

const PZ_FRAGMENT_HEADER = [
    "#ifndef PZ_GRAPH_EMISSION",
    "#define PZ_GRAPH_EMISSION 0",
    "#endif",
    "#ifndef PZ_GRAPH_NORMAL",
    "#define PZ_GRAPH_NORMAL 0",
    "#endif",
    "#ifndef PZ_NORMAL_IMAGE",
    "#define PZ_NORMAL_IMAGE 0",
    "#endif",
    "varying vec2 vPzUv;",
    "uniform vec3 uPzColor;",
    "uniform sampler2D uPzGraphEmission;",
    "uniform sampler2D uPzGraphNormal;",
    "uniform float uPzEmissionStrength;",
    "uniform sampler2D uPzRamp;",
    "uniform float uPzRampFactor;",
    "uniform vec3 uPzFresnelColor;",
    "uniform float uPzFresnelPower;",
    "uniform float uPzFresnelMix;",
    "uniform sampler2D uPzGraphColor;",
    "uniform sampler2D uPzAOMap;",
    "uniform vec3 uPzAOColor;",
    "uniform float uPzAOIntensity;",
    "uniform float uPzAODistance;",
    "uniform float uPzCelSteps;",
    "uniform float uPzCelSmoothness;",
    "uniform float uPzCelSpecularSteps;",
    "uniform float uPzSpecularStrength;",
    "uniform float uPzSpecularEnabled;",
    "uniform float uPzSpecularOpacity;",
    // Reoriented normal mapping in view space. Rotate the geometric normal
    // onto the normal-map result, then apply that same rotation to the bump
    // normal, preserving the detail's strength instead of averaging it away.
    // https://blog.selfshadow.com/publications/blending-in-detail/
    "#if ( defined( USE_NORMALMAP ) && defined( USE_BUMPMAP ) ) || PZ_GRAPH_NORMAL",
    "vec3 pzReorientBump( vec3 surfaceNormal, vec3 mapNormal, vec3 bumpNormal ) {",
    "    vec4 q = vec4( cross( surfaceNormal, mapNormal ), 1.0 + clamp( dot( surfaceNormal, mapNormal ), -1.0, 1.0 ) );",
    // At opposite normals the shortest rotation is ambiguous. Choose a
    // perpendicular axis so imported normals cannot produce a zero quaternion.
    "    if ( q.w < 0.00001 ) {",
    "        vec3 axis = abs( surfaceNormal.z ) < 0.999 ? vec3( 0.0, 0.0, 1.0 ) : vec3( 0.0, 1.0, 0.0 );",
    "        q = vec4( normalize( cross( surfaceNormal, axis ) ), 0.0 );",
    "    }",
    "    return normalize( bumpNormal + 2.0 * cross( q.xyz, cross( q.xyz, bumpNormal ) + q.w * bumpNormal ) / dot( q, q ) );",
    "}",
    "#endif",
    "float pzRampCoord( vec3 color, vec2 uv ) {",
    "#if PZ_RAMP_SRC == 1",
    "    return clamp( uv.x, 0.0, 1.0 );",
    "#elif PZ_RAMP_SRC == 2",
    "    return clamp( uv.y, 0.0, 1.0 );",
    "#else",
    "    return clamp( dot( color, vec3( 0.299, 0.587, 0.114 ) ), 0.0, 1.0 );",
    "#endif",
    "}",
    "vec3 pzComputeColor( vec2 uv ) {",
    "    vec3 pzBase = uPzColor;",
    "#if PZ_RAMP",
    "    vec3 pzRamp = texture2D( uPzRamp, vec2( pzRampCoord( pzBase, uv ), 0.5 ) ).rgb;",
    "    pzBase = mix( pzBase, pzRamp, uPzRampFactor );",
    "#endif",
    "    return pzBase;",
    "}",
].join("\n");

const PZ_MAP_CODE = [
    "#include <map_fragment>",
    "diffuseColor.rgb *= pzComputeColor( vPzUv );",
    "#if PZ_GRAPH_COLOR",
    "diffuseColor.rgb *= texture2D( uPzGraphColor, vPzUv ).rgb;",
    "#endif",
].join("\n");

const PZ_PHYSICAL_CODE = [
    "#include <lights_physical_fragment>",
    "material.specularColor *= uPzSpecularStrength * uPzSpecularEnabled * uPzSpecularOpacity;",
].join("\n");

const PZ_FRESNEL_CODE = [
    "#if defined( USE_NORMALMAP ) && defined( USE_BUMPMAP )",
    "vec3 pzSurfaceNormal = normal;",
    "#endif",
    "#include <normal_fragment_maps>",
    "#if defined( USE_NORMALMAP ) && defined( USE_BUMPMAP )",
    "vec3 pzBumpNormal = perturbNormalArb( -vViewPosition, pzSurfaceNormal, dHdxy_fwd() );",
    "normal = pzReorientBump( pzSurfaceNormal, normal, pzBumpNormal );",
    "#endif",
    "#if PZ_FRESNEL",
    "float pzFresnel = 1.0 - saturate( dot( normalize( normal ), normalize( vViewPosition ) ) );",
    "pzFresnel = pow( pzFresnel, uPzFresnelPower ) * uPzFresnelMix;",
    "diffuseColor.rgb = mix( diffuseColor.rgb, uPzFresnelColor, pzFresnel );",
    "#endif",
].join("\n");

const PZ_LIGHTING_CODE = [
    "#include <lights_fragment_end>",
    "#if PZ_AO",
    "float pzAO = 1.0;",
    "bool pzAOHas = false;",
    "#if PZ_AO_MAP",
    "pzAO = texture2D( uPzAOMap, vPzUv ).r;",
    "pzAOHas = true;",
    "#elif defined( USE_BUMPMAP )",
    "pzAO = texture2D( bumpMap, vPzUv ).r;",
    "pzAOHas = true;",
    "#endif",
    "if ( pzAOHas ) {",
    "    pzAO = pow( clamp( pzAO, 0.0, 1.0 ), max( uPzAODistance, 0.001 ) );",
    "    pzAO = mix( 1.0, pzAO, clamp( uPzAOIntensity, 0.0, 1.0 ) );",
    "    reflectedLight.indirectDiffuse *= mix( vec3( 1.0 ), uPzAOColor, clamp( uPzAOIntensity, 0.0, 1.0 ) ) * pzAO;",
    "    reflectedLight.indirectSpecular *= pzAO;",
    "}",
    "#endif",
    "#if PZ_CEL",
    "float pzCelDiffuse = dot( reflectedLight.directDiffuse + reflectedLight.indirectDiffuse, vec3( 0.299, 0.587, 0.114 ) );",
    "float pzCelSpecular = dot( reflectedLight.directSpecular + reflectedLight.indirectSpecular, vec3( 0.299, 0.587, 0.114 ) );",
    "float pzCelDiffuseLevels = max( uPzCelSteps, 1.0 );",
    "float pzCelSpecularLevels = max( uPzCelSpecularSteps, 1.0 );",
    "float pzCelDiffuseQ = floor( pzCelDiffuse * pzCelDiffuseLevels + 0.5 ) / pzCelDiffuseLevels;",
    "float pzCelSpecularQ = floor( pzCelSpecular * pzCelSpecularLevels + 0.5 ) / pzCelSpecularLevels;",
    "pzCelDiffuseQ = mix( pzCelDiffuseQ, pzCelDiffuse, clamp( uPzCelSmoothness, 0.0, 1.0 ) );",
    "pzCelSpecularQ = mix( pzCelSpecularQ, pzCelSpecular, clamp( uPzCelSmoothness, 0.0, 1.0 ) );",
    "float pzCelDiffuseScale = pzCelDiffuse > 0.0001 ? pzCelDiffuseQ / pzCelDiffuse : 1.0;",
    "float pzCelSpecularScale = pzCelSpecular > 0.0001 ? pzCelSpecularQ / pzCelSpecular : 1.0;",
    "reflectedLight.directDiffuse *= pzCelDiffuseScale;",
    "reflectedLight.indirectDiffuse *= pzCelDiffuseScale;",
    "reflectedLight.directSpecular *= pzCelSpecularScale;",
    "reflectedLight.indirectSpecular *= pzCelSpecularScale;",
    "#endif",
].join("\n");

function pzRandom(seed) {
    var value = seed | 0;
    return function () {
        value = (value + 0x6d2b79f5) | 0;
        var t = Math.imul(value ^ (value >>> 15), 1 | value);
        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}

function pzNoiseCanvas(size, cells, seed) {
    var canvas = null;
    if (typeof document !== "undefined") {
        canvas = document.createElement("canvas");
    } else if (typeof OffscreenCanvas !== "undefined") {
        canvas = new OffscreenCanvas(size, size);
    }
    if (!canvas) return null;
    canvas.width = size;
    canvas.height = size;
    var context = canvas.getContext("2d");
    if (!context || !context.createImageData) return null;
    var image = context.createImageData(size, size);
    var data = image.data;
    var random = pzRandom(seed);
    var octaves = 3;
    var frequency = Math.max(2, Math.round(cells));
    var amplitude = 1;
    var total = 0;
    var values = new Float32Array(size * size);
    for (var o = 0; o < octaves; o++) {
        var lattice = new Float32Array((frequency + 1) * (frequency + 1));
        for (var i = 0; i < lattice.length; i++) {
            lattice[i] = random();
        }
        for (var y = 0; y < size; y++) {
            var gy = (y / size) * frequency;
            var y0 = Math.min(gy | 0, frequency - 1);
            var fy = gy - y0;
            var sy = fy * fy * (3 - 2 * fy);
            for (var x = 0; x < size; x++) {
                var gx = (x / size) * frequency;
                var x0 = Math.min(gx | 0, frequency - 1);
                var fx = gx - x0;
                var sx = fx * fx * (3 - 2 * fx);
                var i00 = x0 + y0 * (frequency + 1);
                var i10 = i00 + 1;
                var i01 = i00 + frequency + 1;
                var i11 = i01 + 1;
                var top = lattice[i00] + (lattice[i10] - lattice[i00]) * sx;
                var bottom = lattice[i01] + (lattice[i11] - lattice[i01]) * sx;
                values[x + y * size] += (top + (bottom - top) * sy) * amplitude;
            }
        }
        total += amplitude;
        amplitude *= 0.5;
        frequency *= 2;
    }
    for (var p = 0; p < size * size; p++) {
        var gray = Math.round((values[p] / total) * 255);
        var index = p * 4;
        data[index] = gray;
        data[index + 1] = gray;
        data[index + 2] = gray;
        data[index + 3] = 255;
    }
    context.putImageData(image, 0, 0);
    return canvas;
}

function pzParseStopColor(value) {
    var color = { r: 0, g: 0, b: 0, a: 1 };
    if (typeof value === "string" && value.indexOf("(") >= 0) {
        var parts = value.split("(")[1].split(")")[0].split(",");
        color.r = parseInt(parts[0], 10) || 0;
        color.g = parseInt(parts[1], 10) || 0;
        color.b = parseInt(parts[2], 10) || 0;
        color.a = parts[3] !== undefined ? parseFloat(parts[3]) : 1;
        return color;
    }
    if (Array.isArray(value)) {
        color.r = Math.round((value[0] || 0) * 255);
        color.g = Math.round((value[1] || 0) * 255);
        color.b = Math.round((value[2] || 0) * 255);
        color.a = value[3] !== undefined ? value[3] : 1;
    }
    return color;
}

function pzSampleStops(stops, t, interpolation) {
    if (!stops || !stops.length) {
        return { r: 255, g: 255, b: 255, a: 255 };
    }
    var first = pzParseStopColor(stops[0].color);
    var last = pzParseStopColor(stops[stops.length - 1].color);
    if (t <= stops[0].position) return first;
    if (t >= stops[stops.length - 1].position) return last;
    for (var i = 0; i < stops.length - 1; i++) {
        var a = stops[i];
        var b = stops[i + 1];
        if (t < a.position || t > b.position) continue;
        var span = Math.max(b.position - a.position, 0.00001);
        var f = (t - a.position) / span;
        if (interpolation === 1) {
            f = 0;
        } else if (interpolation === 2) {
            f = f * f * (3 - 2 * f);
        }
        var ca = pzParseStopColor(a.color);
        var cb = pzParseStopColor(b.color);
        return {
            r: ca.r + (cb.r - ca.r) * f,
            g: ca.g + (cb.g - ca.g) * f,
            b: ca.b + (cb.b - ca.b) * f,
            a: ca.a + (cb.a - ca.a) * f,
        };
    }
    return last;
}

function pzDrawGradient(data, stops, interpolation) {
    var sorted = (stops || []).slice().sort(function (a, b) {
        return a.position - b.position;
    });
    var count = data.length / 4;
    for (var i = 0; i < count; i++) {
        var t = count > 1 ? i / (count - 1) : 0;
        var color = pzSampleStops(sorted, t, interpolation || 0);
        var index = i * 4;
        data[index] = Math.max(0, Math.min(255, Math.round(color.r)));
        data[index + 1] = Math.max(0, Math.min(255, Math.round(color.g)));
        data[index + 2] = Math.max(0, Math.min(255, Math.round(color.b)));
        data[index + 3] = Math.max(0, Math.min(255, Math.round(color.a * 255)));
    }
}

    return {
  WRAP_VALUES, PZ_RAMP_SOURCE, PZ_RAMP_INTERPOLATION, PZ_VERTEX_HEADER,
  PZ_UV_PROJECTION_CODE, PZ_FRAGMENT_HEADER, PZ_MAP_CODE,
  PZ_PHYSICAL_CODE, PZ_FRESNEL_CODE, PZ_LIGHTING_CODE, pzRandom,
  pzNoiseCanvas, pzParseStopColor, pzSampleStops, pzDrawGradient,
 };
};

text./plugins/material-plus/uv-custom.js:
"use strict";

// UV Custom Material mirrors CM3's native Custom Material, but lays out the
// UVs of 3D Text and extruded geometry with the shared Material+ layout
// (uv-layout.js) so a texture keeps one texel density on every face. CM3's
// native Custom Material is left completely untouched, so existing projects
// keep their original look.

const UV_CUSTOM_MATERIAL_ID = "uvcustom";
const UV_CUSTOM_MATERIAL_NAME = "UV Custom Material";

const uvCustomState = {
  active: false,
  PZ: null,
  THREE: null,
  plugin: null,
  previousFactory: undefined,
  hadPreviousFactory: false,
  factory: null,
  layout: null,
};

const UV_LAYOUT_SOURCE = "./plugins/material-plus/uv-layout.js";

// Materials that still hold a normalized geometry, so deactivate() can restore.
const activeMaterials = new Set();

function uvReadNumber(property, frame, fallback) {
  try {
    const value = property?.get?.(frame);
    return Number.isFinite(Number(value)) ? Number(value) : fallback;
  } catch (_error) {
    // Host dynamic properties can be unavailable before native load.
    return fallback;
  }
}

function uvReadColor(property, frame, fallback) {
  try {
    const value = property?.get?.(frame);
    if (Array.isArray(value) && value.length >= 3) {
      return [Number(value[0]) || 0, Number(value[1]) || 0, Number(value[2]) || 0];
    }
  } catch (_error) {
    // Use the supplied fallback below.
  }
  return fallback.slice();
}

function uvReadVector2(property, frame, fallback) {
  try {
    const value = property?.get?.(frame);
    if (Array.isArray(value) && value.length >= 2) {
      return [Number(value[0]) || 0, Number(value[1]) || 0];
    }
  } catch (_error) {
    // Use the supplied fallback below.
  }
  return fallback.slice();
}

function uvOptionValue(property, fallback) {
  const value = Number(property?.value);
  return Number.isFinite(value) ? value : fallback;
}

/* ------------------------------------------------------------- material API */

function uvApplyRenderSettings(material) {
  if (!material.threeObj) return;
  const transparent = uvOptionValue(material.properties.transparent, 0) === 1;
  const blending = [
    stateThree().NoBlending,
    stateThree().NormalBlending,
    stateThree().AdditiveBlending,
    stateThree().SubtractiveBlending,
    stateThree().MultiplyBlending,
  ][uvOptionValue(material.properties.blending, 1)];
  material.threeObj.transparent = transparent;
  material.threeObj.blending = blending ?? stateThree().NormalBlending;
  material.threeObj.needsUpdate = true;
}

function stateThree() {
  return uvCustomState.THREE;
}

function uvWrapValues() {
  const THREE = stateThree();
  return [THREE.ClampToEdgeWrapping, THREE.RepeatWrapping, THREE.MirroredRepeatWrapping];
}

function uvDisposeTexture(material, key, property) {
  const asset = material[key];
  material[key] = null;
  if (material.threeObj && material.threeObj[property]) {
    material.threeObj[property].dispose?.();
    material.threeObj[property] = null;
  }
  if (asset) {
    try {
      material.parentProject?.assets?.unload(asset);
    } catch (error) {
      console.warn("[Zoidium] UV Custom: could not unload a texture asset", error);
    }
  }
}

function uvLoadTexture(material, key, property, value) {
  uvDisposeTexture(material, key, property);
  if (!value || !material.parentProject?.assets || !material.threeObj) return;
  material[key] = new uvCustomState.PZ.asset.image(material.parentProject.assets.load(value));
  const texture = material[key].getTexture(true);
  const wrap = uvOptionValue(material.properties.wrap, 1) || 1;
  texture.wrapS = uvWrapValues()[wrap];
  texture.wrapT = uvWrapValues()[wrap];
  material.threeObj[property] = texture;
  material.threeObj.needsUpdate = true;
}

function uvApplyTextureSettings(material, frame) {
  const map = material.threeObj?.map;
  const normalMap = material.threeObj?.normalMap;
  const repeat = uvReadVector2(material.properties.repeat, frame, [1, 1]);
  const offset = uvReadVector2(material.properties.offset, frame, [0, 0]);
  const center = uvReadVector2(material.properties.center, frame, [0, 0]);
  const rotation = uvReadNumber(material.properties.rotation, frame, 0);
  for (const texture of [map, normalMap]) {
    if (!texture) continue;
    texture.repeat.set(repeat[0], repeat[1]);
    texture.offset.set(offset[0], offset[1]);
    texture.center.set(center[0], center[1]);
    texture.rotation = rotation;
  }
}

function uvSyncReflection(material) {
  const enabled = uvOptionValue(material.properties.reflection, 0) === 1;
  const envMap = material.parentLayer?.envMap;
  if (!enabled || !envMap) {
    if (material.threeObj?.envMap) {
      envMap?.releaseTexture?.();
      material.threeObj.envMap = null;
      material.threeObj.needsUpdate = true;
    }
    return;
  }
  if (!material.threeObj?.envMap) {
    material.threeObj.envMap = envMap.getTexture();
    material.threeObj.needsUpdate = true;
  }
}

function uvTrackMaterial(material, plugin) {
  uvCustomState.PZ.zoidium?.trackPluginMaterial?.(
    material,
    {
      id: plugin.id || "material-plus",
      name: plugin.name || "Material+",
      version: String(plugin.version || "1"),
      author: plugin.author || "Zoidium",
      material: UV_CUSTOM_MATERIAL_ID,
      materialName: UV_CUSTOM_MATERIAL_NAME,
      compatibility: "incompatible",
    },
    false
  );
}

function createMaterialFactory(plugin) {
  const PZ = uvCustomState.PZ;
  const propertyDefinitions = {
    color: {
      dynamic: true,
      group: true,
      objects: [
        { dynamic: true, name: "Color.R", type: PZ.property.type.NUMBER, value: 1, min: 0, max: 1 },
        { dynamic: true, name: "Color.G", type: PZ.property.type.NUMBER, value: 1, min: 0, max: 1 },
        { dynamic: true, name: "Color.B", type: PZ.property.type.NUMBER, value: 1, min: 0, max: 1 },
      ],
      name: "Color",
      type: PZ.property.type.COLOR,
    },
    emissive: {
      dynamic: true,
      group: true,
      objects: [
        { dynamic: true, name: "Emissive.R", type: PZ.property.type.NUMBER, value: 0, min: 0, max: 1 },
        { dynamic: true, name: "Emissive.G", type: PZ.property.type.NUMBER, value: 0, min: 0, max: 1 },
        { dynamic: true, name: "Emissive.B", type: PZ.property.type.NUMBER, value: 0, min: 0, max: 1 },
      ],
      name: "Emissive",
      type: PZ.property.type.COLOR,
    },
    roughness: {
      name: "Roughness",
      type: PZ.property.type.NUMBER,
      value: 0.5,
      min: 0,
      max: 1,
      step: 0.01,
    },
    metalness: {
      name: "Metalness",
      type: PZ.property.type.NUMBER,
      value: 0.5,
      min: 0,
      max: 1,
      step: 0.01,
    },
    texture: {
      name: "Texture",
      type: PZ.property.type.ASSET,
      assetType: PZ.asset.type.IMAGE,
      accept: "image/*",
      value: null,
      changed: function () {
        const material = this.parentObject;
        if (material?._zoidiumLoading) return;
        uvLoadTexture(material, "texture", "map", this.value);
      },
    },
    transparent: {
      name: "Transparency",
      type: PZ.property.type.OPTION,
      value: 0,
      changed: function () {
        const material = this.parentObject;
        if (material?._zoidiumLoading) return;
        uvApplyRenderSettings(material);
      },
      items: "off;on",
    },
    opacity: {
      dynamic: true,
      name: "Opacity",
      type: PZ.property.type.NUMBER,
      value: 1,
      min: 0,
      max: 1,
      step: 0.01,
    },
    blending: {
      name: "Blending",
      type: PZ.property.type.OPTION,
      value: 1,
      changed: function () {
        const material = this.parentObject;
        if (material?._zoidiumLoading) return;
        uvApplyRenderSettings(material);
      },
      items: "none;normal;additive;subtractive;multiply",
    },
    side: {
      name: "Render side",
      type: PZ.property.type.OPTION,
      value: 0,
      changed: function () {
        const material = this.parentObject;
        material.threeObj.side = this.value;
      },
      items: "front;back;both",
    },
    normalMap: {
      name: "Normal map",
      type: PZ.property.type.ASSET,
      assetType: PZ.asset.type.IMAGE,
      accept: "image/*",
      value: null,
      changed: function () {
        const material = this.parentObject;
        if (material?._zoidiumLoading) return;
        uvLoadTexture(material, "normalMap", "normalMap", this.value);
      },
    },
    normalScale: {
      name: "Normal scale",
      type: PZ.property.type.NUMBER,
      value: 1,
      min: 0,
      step: 0.01,
      decimals: 3,
    },
    wrap: {
      name: "Wrap",
      type: PZ.property.type.OPTION,
      value: 1,
      changed: function () {
        const material = this.parentObject;
        for (const texture of [material.threeObj?.map, material.threeObj?.normalMap]) {
          if (!texture) continue;
          texture.wrapS = uvWrapValues()[this.value];
          texture.wrapT = uvWrapValues()[this.value];
          texture.needsUpdate = true;
        }
      },
      items: "none;tile;reflect",
    },
    repeat: {
      dynamic: true,
      group: true,
      objects: [
        { dynamic: true, name: "Repeat.U", type: PZ.property.type.NUMBER, step: 0.1, decimals: 3, value: 1 },
        { dynamic: true, name: "Repeat.V", type: PZ.property.type.NUMBER, step: 0.1, decimals: 3, value: 1 },
      ],
      name: "Repeat",
      type: PZ.property.type.VECTOR2,
      step: 0.1,
      decimals: 3,
      linkRatio: true,
    },
    offset: {
      dynamic: true,
      group: true,
      objects: [
        { dynamic: true, name: "Offset.U", type: PZ.property.type.NUMBER, step: 0.1, decimals: 3, value: 0 },
        { dynamic: true, name: "Offset.V", type: PZ.property.type.NUMBER, step: 0.1, decimals: 3, value: 0 },
      ],
      name: "Offset",
      type: PZ.property.type.VECTOR2,
      step: 0.1,
      decimals: 3,
    },
    center: {
      dynamic: true,
      group: true,
      objects: [
        { dynamic: true, name: "Center.U", type: PZ.property.type.NUMBER, step: 0.1, decimals: 3, value: 0 },
        { dynamic: true, name: "Center.V", type: PZ.property.type.NUMBER, step: 0.1, decimals: 3, value: 0 },
      ],
      name: "Center",
      type: PZ.property.type.VECTOR2,
      step: 0.1,
      decimals: 3,
    },
    rotation: {
      dynamic: true,
      name: "Rotation",
      type: PZ.property.type.NUMBER,
      value: 0,
      step: 0.5,
      scaleFactor: Math.PI / 180,
    },
    reflection: {
      name: "Reflection",
      type: PZ.property.type.OPTION,
      value: 0,
      changed: function () {
        const material = this.parentObject;
        if (material?._zoidiumLoading) return;
        uvSyncReflection(material);
      },
      items: "off;on",
    },
  };

  return function () {
    const material = this;
    material.defaultName = UV_CUSTOM_MATERIAL_NAME;
    material.texture = null;
    material.normalMap = null;
    material._zoidiumLoading = true;
    material.properties.addAll(propertyDefinitions);
    material._zoidiumLoading = false;

    material.load = function (data) {
      const THREE = stateThree();
      material._zoidiumLoading = true;
      material.threeObj = new THREE.MeshStandardMaterial({ color: 0xffffff });
      material.threeObj.premultipliedAlpha = true;
      try {
        material.properties.load(data && data.properties);
      } finally {
        material._zoidiumLoading = false;
      }
      uvLoadTexture(material, "texture", "map", material.properties.texture.value);
      uvLoadTexture(material, "normalMap", "normalMap", material.properties.normalMap.value);
      uvApplyRenderSettings(material);
      uvSyncReflection(material);
      uvCustomState.layout.ensureMaterial(material);
      activeMaterials.add(material);
      uvTrackMaterial(material, plugin);
    };

    material.update = function (frame) {
      if (!material.threeObj) return;

      const color = uvReadColor(material.properties.color, frame, [1, 1, 1]);
      const emissive = uvReadColor(material.properties.emissive, frame, [0, 0, 0]);
      material.threeObj.color.setRGB(color[0], color[1], color[2]);
      material.threeObj.emissive.setRGB(emissive[0], emissive[1], emissive[2]);
      material.threeObj.roughness = Math.max(
        0,
        uvReadNumber(material.properties.roughness, frame, 0.5)
      );
      material.threeObj.metalness = Math.max(
        0,
        uvReadNumber(material.properties.metalness, frame, 0.5)
      );
      const normalScale = Math.max(
        0,
        uvReadNumber(material.properties.normalScale, frame, 1)
      );
      material.threeObj.normalScale?.set?.(normalScale, normalScale);
      material.threeObj.opacity = Math.max(
        0,
        Math.min(1, uvReadNumber(material.properties.opacity, frame, 1))
      );

      uvApplyTextureSettings(material, frame);
      uvCustomState.layout.ensureMaterial(material);
      if (
        material._zoidiumReflectionLayer !== material.parentLayer ||
        material._zoidiumReflectionSource !== material.parentLayer?.envMap
      ) {
        material._zoidiumReflectionLayer = material.parentLayer;
        material._zoidiumReflectionSource = material.parentLayer?.envMap;
        uvSyncReflection(material);
      }
    };

    material.prepare = async function () {
      if (material.texture) await material.texture.loading;
      if (material.normalMap) await material.normalMap.loading;
    };

    material.toJSON = function () {
      return { type: material.type, properties: material.properties };
    };

    material.unload = function () {
      uvCustomState.PZ.zoidium?.untrackPluginMaterial?.(material);
      activeMaterials.delete(material);
      uvCustomState.layout.releaseMaterial(material);
      uvDisposeTexture(material, "texture", "map");
      uvDisposeTexture(material, "normalMap", "normalMap");
      if (material.threeObj?.envMap) {
        material.parentLayer?.envMap?.releaseTexture?.();
        material.threeObj.envMap = null;
      }
      material.threeObj?.dispose?.();
      material.threeObj = null;
    };
  };
}

function activate(context) {
  if (uvCustomState.active) return;

  const PZ = context.PZ || context.window?.PZ;
  const THREE =
    context.window?.THREE || (typeof globalThis !== "undefined" ? globalThis.THREE : null);
  if (!PZ?.material?.fnList || !PZ?.asset?.image || !THREE?.MeshStandardMaterial) {
    throw new Error("Material+ UV Custom Material requires the CM3 material and Three.js APIs.");
  }

  uvCustomState.layout = new Function(context.getAsset("text", UV_LAYOUT_SOURCE))()();
  uvCustomState.active = true;
  uvCustomState.PZ = PZ;
  uvCustomState.THREE = THREE;
  uvCustomState.plugin = context.plugin || {};
  // Register cleanup before mutating the host so a failed or disabled
  // plugin always restores the previous material factory.
  context.lifecycle?.onDispose?.(deactivate);
  uvCustomState.hadPreviousFactory = Object.prototype.hasOwnProperty.call(
    PZ.material.fnList,
    UV_CUSTOM_MATERIAL_ID
  );
  uvCustomState.previousFactory = PZ.material.fnList[UV_CUSTOM_MATERIAL_ID];
  uvCustomState.factory = Promise.resolve(createMaterialFactory(uvCustomState.plugin));
  uvCustomState.factory._zoidiumMaterialMode = "native";
  PZ.material.fnList[UV_CUSTOM_MATERIAL_ID] = uvCustomState.factory;
}

function deactivate() {
  if (!uvCustomState.active) return;
  for (const material of Array.from(activeMaterials)) uvCustomState.layout.releaseMaterial(material);
  if (uvCustomState.PZ?.material?.fnList?.[UV_CUSTOM_MATERIAL_ID] === uvCustomState.factory) {
    if (uvCustomState.hadPreviousFactory) {
      uvCustomState.PZ.material.fnList[UV_CUSTOM_MATERIAL_ID] = uvCustomState.previousFactory;
    } else {
      delete uvCustomState.PZ.material.fnList[UV_CUSTOM_MATERIAL_ID];
    }
  }
  uvCustomState.active = false;
  uvCustomState.PZ = null;
  uvCustomState.THREE = null;
  uvCustomState.plugin = null;
  uvCustomState.previousFactory = undefined;
  uvCustomState.hadPreviousFactory = false;
  uvCustomState.factory = null;
  uvCustomState.layout = null;
}

module.exports = {
  UV_CUSTOM_MATERIAL_ID,
  UV_CUSTOM_MATERIAL_NAME,
  activate,
  deactivate,
};

text./plugins/material-plus/uv-layout.js:
// Shared texture layout for Material+ materials.
//
// CM3 builds 3D Text and extruded shapes with Three.js TextGeometry /
// ExtrudeGeometry, whose WorldUVGenerator maps UVs in object units: caps use raw
// x/y and side walls project x|y against z, so curved and slanted walls shear.
// Every Material+ material that samples a texture through the mesh UVs uses
// this layout instead: caps use the text bounds, side walls unwrap along the
// outline (arc length in U, depth in V), and the text height sets the texture
// unit. The unwrap works on the finished geometry only: it rebuilds each
// outline from the side walls, so it needs no access to the font or the source
// shapes.
//
// The original UVs are stored on the geometry and restored when the last
// layout material leaves the object, so native CM3 materials keep their look.
// Effectors render a working copy; they publish the source geometry as
// `mesh.__zoidiumSourceGeometry` and rebuild when `__zoidiumUvRevision` changes.
return function createUvLayout() {
"use strict";

const UV_EPSILON = 1e-6;
const UV_DISTANCE_EPSILON = 1e-12;
const UV_QUANTIZE = 1e4;

/* --------------------------------------------------------------- UV unwrap */

function uvQuantize(x, y) {
  return `${Math.round(x * UV_QUANTIZE)},${Math.round(y * UV_QUANTIZE)}`;
}

// Rebuild the closed outline(s) of an extruded legacy Geometry from its side
// walls: the two lowest vertices of a wall triangle are consecutive outline
// points. This recovers the contour order without the original shapes.
function uvReconstructContours(geometry) {
  const vertices = geometry.vertices;
  const faces = geometry.faces;
  const nodes = new Map();
  const adjacency = new Map();

  function addEdge(a, b) {
    const keyA = uvQuantize(a.x, a.y);
    const keyB = uvQuantize(b.x, b.y);
    if (keyA === keyB) return;
    if (!nodes.has(keyA)) {
      nodes.set(keyA, { x: a.x, y: a.y });
      adjacency.set(keyA, new Set());
    }
    if (!nodes.has(keyB)) {
      nodes.set(keyB, { x: b.x, y: b.y });
      adjacency.set(keyB, new Set());
    }
    adjacency.get(keyA).add(keyB);
    adjacency.get(keyB).add(keyA);
  }

  for (let faceIndex = 0; faceIndex < faces.length; faceIndex += 1) {
    const face = faces[faceIndex];
    const indices = [face.a, face.b, face.c];
    let minZ = Infinity;
    let maxZ = -Infinity;
    for (let index = 0; index < indices.length; index += 1) {
      const z = vertices[indices[index]]?.z ?? 0;
      if (z < minZ) minZ = z;
      if (z > maxZ) maxZ = z;
    }
    if (maxZ - minZ <= UV_EPSILON) continue; // cap plane

    const bottom = [];
    for (let index = 0; index < indices.length; index += 1) {
      if (Math.abs(vertices[indices[index]].z - minZ) <= UV_EPSILON) {
        bottom.push(vertices[indices[index]]);
      }
    }
    if (bottom.length === 2) addEdge(bottom[0], bottom[1]);
  }

  const visited = new Set();
  const contours = [];
  for (const start of adjacency.keys()) {
    if (visited.has(start)) continue;
    const cycle = [];
    let previous = null;
    let current = start;
    while (current && !visited.has(current)) {
      visited.add(current);
      cycle.push(nodes.get(current));
      const neighbors = Array.from(adjacency.get(current));
      let next = neighbors.find((key) => key !== previous && !visited.has(key));
      if (!next && neighbors.includes(start)) next = start;
      previous = current;
      current = next;
    }
    if (cycle.length >= 3) contours.push(cycle);
  }
  return contours;
}

function uvPrepareContours(contours) {
  const prepared = [];
  for (let index = 0; index < contours.length; index += 1) {
    const points = contours[index];
    if (!Array.isArray(points) || points.length < 2) continue;

    const cumulative = [0];
    let total = 0;
    for (let point = 0; point < points.length; point += 1) {
      const current = points[point];
      const next = points[(point + 1) % points.length];
      total += Math.hypot(next.x - current.x, next.y - current.y);
      cumulative.push(total);
    }
    if (!(total > 0)) continue;
    prepared.push({ points, cumulative, total });
  }
  return prepared;
}

// Keep segments in their original contour order. Bounding boxes skip distant
// ranges without changing the epsilon ties or the closing seam's first match.
// Spatially reordering nearest segments would change UVs on ambiguous walls.
function uvBuildOutlineIndex(prepared) {
  const segments = [];
  for (const contour of prepared) {
    for (let point = 0; point < contour.points.length; point += 1) {
      const a = contour.points[point];
      const b = contour.points[(point + 1) % contour.points.length];
      segments.push({ contour, point, index: segments.length,
        minX: Math.min(a.x, b.x), minY: Math.min(a.y, b.y),
        maxX: Math.max(a.x, b.x), maxY: Math.max(a.y, b.y),
        centerX: (a.x + b.x) / 2, centerY: (a.y + b.y) / 2 });
    }
  }
  function build(start, end) {
    const node = { start, end, minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity };
    if (end - start > 8) {
      const middle = Math.floor((start + end) / 2);
      node.left = build(start, middle);
      node.right = build(middle, end);
      node.minX = Math.min(node.left.minX, node.right.minX);
      node.minY = Math.min(node.left.minY, node.right.minY);
      node.maxX = Math.max(node.left.maxX, node.right.maxX);
      node.maxY = Math.max(node.left.maxY, node.right.maxY);
    } else {
      for (let index = start; index < end; index += 1) {
        const { contour, point } = segments[index];
        const a = contour.points[point];
        const b = contour.points[(point + 1) % contour.points.length];
        node.minX = Math.min(node.minX, a.x, b.x);
        node.minY = Math.min(node.minY, a.y, b.y);
        node.maxX = Math.max(node.maxX, a.x, b.x);
        node.maxY = Math.max(node.maxY, a.y, b.y);
      }
    }
    return node;
  }
  // Bevel rings can overlap throughout contour order. A second tree groups
  // segments spatially for nearest searches; the ordered tree remains the
  // exact fallback for epsilon transitions.
  function buildSpatial(entries) {
    const node = { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity };
    for (const segment of entries) {
      node.minX = Math.min(node.minX, segment.minX);
      node.minY = Math.min(node.minY, segment.minY);
      node.maxX = Math.max(node.maxX, segment.maxX);
      node.maxY = Math.max(node.maxY, segment.maxY);
    }
    if (entries.length <= 8) node.indices = entries.map(segment => segment.index);
    else {
      const axis = node.maxX - node.minX >= node.maxY - node.minY ? "centerX" : "centerY";
      entries.sort((a, b) => a[axis] - b[axis] || a.index - b.index);
      const middle = Math.floor(entries.length / 2);
      node.left = buildSpatial(entries.slice(0, middle));
      node.right = buildSpatial(entries.slice(middle));
    }
    return node;
  }
  return { segments, root: build(0, segments.length), spatialRoot: buildSpatial(segments.slice()) };
}

// Every segment tied for the minimum distance is returned: the outline's
// closing point is shared by two segments and projects to arc 0 and arc total.
function uvOrderedCandidates(outline, x, y, scale) {
  let bestDistanceSquared = Infinity;
  const candidates = [];

  function visit(node) {
    const boxDx = Math.max(node.minX - x, 0, x - node.maxX);
    const boxDy = Math.max(node.minY - y, 0, y - node.maxY);
    // Extra slack makes pruning conservative at floating-point boundaries.
    const lowerBound = boxDx * boxDx + boxDy * boxDy;
    const slack = UV_DISTANCE_EPSILON + Number.EPSILON * 8 * Math.max(1, lowerBound);
    if (lowerBound > bestDistanceSquared + slack) return;
    if (node.left) {
      visit(node.left);
      visit(node.right);
      return;
    }
    for (let index = node.start; index < node.end; index += 1) {
      const { contour, point } = outline.segments[index];
      const points = contour.points;
      const a = points[point];
      const b = points[(point + 1) % points.length];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const lengthSquared = dx * dx + dy * dy;

      let t = 0;
      if (lengthSquared > 0) {
        t = ((x - a.x) * dx + (y - a.y) * dy) / lengthSquared;
        if (t < 0) t = 0;
        else if (t > 1) t = 1;
      }

      const px = a.x + dx * t;
      const py = a.y + dy * t;
      const distanceSquared = (x - px) * (x - px) + (y - py) * (y - py);

      if (distanceSquared < bestDistanceSquared - UV_DISTANCE_EPSILON) {
        bestDistanceSquared = distanceSquared;
        candidates.length = 0;
      } else if (distanceSquared > bestDistanceSquared + UV_DISTANCE_EPSILON) {
        continue;
      }

      const arc = contour.cumulative[point] + Math.sqrt(lengthSquared) * t;
      candidates.push({
        arc,
        total: contour.total,
        u: scale > 0 ? arc / scale : contour.total > 0 ? arc / contour.total : 0,
        distanceSquared,
      });
    }
  }
  visit(outline.root);
  return candidates;
}

// Most queries have one nearest segment, or exact endpoint/seam ties. Find
// that neighborhood first instead of walking thousands of earlier segments.
// If distances lie in the epsilon transition band, use the ordered search:
// its non-transitive tolerance can depend on an earlier, farther segment.
function uvOutlineCandidates(outline, x, y, scale) {
  let minimum = Infinity;
  const nearby = [];
  function boxDistance(node) {
    const dx = Math.max(node.minX - x, 0, x - node.maxX);
    const dy = Math.max(node.minY - y, 0, y - node.maxY);
    return dx * dx + dy * dy;
  }
  function distance(index) {
    const { contour, point } = outline.segments[index];
    const a = contour.points[point];
    const b = contour.points[(point + 1) % contour.points.length];
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const lengthSquared = dx * dx + dy * dy;
    let t = 0;
    if (lengthSquared > 0) {
      t = ((x - a.x) * dx + (y - a.y) * dy) / lengthSquared;
      if (t < 0) t = 0;
      else if (t > 1) t = 1;
    }
    const px = a.x + dx * t;
    const py = a.y + dy * t;
    return { index, contour, point, t, lengthSquared,
      distanceSquared: (x - px) * (x - px) + (y - py) * (y - py) };
  }
  function visit(node, collect) {
    const lowerBound = boxDistance(node);
    const slack = UV_DISTANCE_EPSILON * 4 + Number.EPSILON * 8 * Math.max(1, lowerBound);
    if (lowerBound > minimum + slack) return;
    if (node.left) {
      // First pass uses spatial order; the collected matches are sorted back
      // into contour order before applying the original tie rules.
      const rightFirst = !collect && boxDistance(node.right) < boxDistance(node.left);
      visit(rightFirst ? node.right : node.left, collect);
      visit(rightFirst ? node.left : node.right, collect);
    } else {
      for (const index of node.indices) {
        const match = distance(index);
        if (collect) {
          if (match.distanceSquared <= minimum + UV_DISTANCE_EPSILON * 4) nearby.push(match);
        } else if (match.distanceSquared < minimum) minimum = match.distanceSquared;
      }
    }
  }
  visit(outline.spatialRoot, false);
  visit(outline.spatialRoot, true);
  if (nearby.some(match => match.distanceSquared > minimum + UV_DISTANCE_EPSILON / 2)) {
    return uvOrderedCandidates(outline, x, y, scale);
  }
  nearby.sort((a, b) => a.index - b.index);
  return nearby.map(({ contour, point, t, lengthSquared, distanceSquared }) => {
    const arc = contour.cumulative[point] + Math.sqrt(lengthSquared) * t;
    return { arc, total: contour.total,
      u: scale > 0 ? arc / scale : contour.total > 0 ? arc / contour.total : 0,
      distanceSquared };
  });
}

function uvNearestTo(candidates, anchorU) {
  let best = candidates[0];
  let bestDelta = Math.abs(best.u - anchorU);
  for (let index = 1; index < candidates.length; index += 1) {
    const delta = Math.abs(candidates[index].u - anchorU);
    if (delta < bestDelta) {
      bestDelta = delta;
      best = candidates[index];
    }
  }
  return best;
}

function uvGeometryBounds(vertices) {
  const bounds = {
    minX: Infinity,
    minY: Infinity,
    minZ: Infinity,
    maxX: -Infinity,
    maxY: -Infinity,
    maxZ: -Infinity,
  };
  for (let index = 0; index < vertices.length; index += 1) {
    const vertex = vertices[index];
    if (!vertex) continue;
    if (vertex.x < bounds.minX) bounds.minX = vertex.x;
    if (vertex.y < bounds.minY) bounds.minY = vertex.y;
    if (vertex.z < bounds.minZ) bounds.minZ = vertex.z;
    if (vertex.x > bounds.maxX) bounds.maxX = vertex.x;
    if (vertex.y > bounds.maxY) bounds.maxY = vertex.y;
    if (vertex.z > bounds.maxZ) bounds.maxZ = vertex.z;
  }
  return bounds;
}

function uvFaceIndices(face) {
  const indices = [face.a, face.b, face.c];
  if (typeof face.d === "number") indices.push(face.d);
  return indices;
}

function uvIsEligibleGeometry(geometry) {
  if (!geometry || geometry.__zoidiumUvNormalized || geometry.__zoidiumUvSkipped) {
    return false;
  }
  if (geometry.type !== "TextGeometry" && geometry.type !== "ExtrudeGeometry") {
    return false;
  }
  if (!Array.isArray(geometry.vertices) || !Array.isArray(geometry.faces)) {
    return false;
  }
  const layers = geometry.faceVertexUvs;
  if (!layers || !Array.isArray(layers[0]) || layers[0].length === 0) return false;
  const options = geometry.parameters && geometry.parameters.options;
  if (options && options.extrudePath) return false;
  return true;
}

function uvNormalizeGeometry(geometry) {
  const vertices = geometry.vertices;
  const uvs = geometry.faceVertexUvs[0];
  const bounds = uvGeometryBounds(vertices);
  const sizeX = bounds.maxX - bounds.minX;
  const sizeY = bounds.maxY - bounds.minY;
  const sizeZ = bounds.maxZ - bounds.minZ;
  // One texel density on every face: the text height sets the texture unit.
  const scale = sizeY > 0 ? sizeY : sizeX > 0 ? sizeX : sizeZ > 0 ? sizeZ : 1;
  const prepared = uvPrepareContours(uvReconstructContours(geometry));
  if (prepared.length === 0) return false;
  const outline = uvBuildOutlineIndex(prepared);
  // A vertex is shared by multiple wall triangles. This cache lasts only for
  // this normalization, so all geometry, contour and scale inputs are current.
  const vertexCandidates = new Map();

  for (let faceIndex = 0; faceIndex < geometry.faces.length; faceIndex += 1) {
    const face = geometry.faces[faceIndex];
    const faceUvs = uvs[faceIndex];
    if (!face || !Array.isArray(faceUvs)) continue;

    const indices = uvFaceIndices(face);
    let minFaceZ = Infinity;
    let maxFaceZ = -Infinity;
    let centroidX = 0;
    let centroidY = 0;
    let counted = 0;
    for (let index = 0; index < indices.length; index += 1) {
      const vertex = vertices[indices[index]];
      if (!vertex) continue;
      if (vertex.z < minFaceZ) minFaceZ = vertex.z;
      if (vertex.z > maxFaceZ) maxFaceZ = vertex.z;
      centroidX += vertex.x;
      centroidY += vertex.y;
      counted += 1;
    }

    const isCap = maxFaceZ - minFaceZ <= UV_EPSILON;
    let anchorU = 0;
    if (!isCap && counted > 0) {
      const anchor = uvOutlineCandidates(
        outline,
        centroidX / counted,
        centroidY / counted,
        scale
      )[0];
      anchorU = anchor ? anchor.u : 0;
    }

    for (let index = 0; index < faceUvs.length; index += 1) {
      const uv = faceUvs[index];
      const vertex = vertices[indices[index]];
      if (!uv || !vertex || typeof uv.set !== "function") continue;

      if (isCap) {
        uv.set((vertex.x - bounds.minX) / scale, (vertex.y - bounds.minY) / scale);
        continue;
      }

      const vertexIndex = indices[index];
      let candidates = vertexCandidates.get(vertexIndex);
      if (!candidates) {
        candidates = uvOutlineCandidates(outline, vertex.x, vertex.y, scale);
        vertexCandidates.set(vertexIndex, candidates);
      }
      const match = candidates.length > 0 ? uvNearestTo(candidates, anchorU) : null;
      uv.set(match ? match.u : anchorU, (vertex.z - bounds.minZ) / scale);
    }
  }

  if (geometry.uvsNeedUpdate !== undefined) geometry.uvsNeedUpdate = true;
  return true;
}


function uvCloneFaceVertexUvs(geometry) {
  const layers = geometry.faceVertexUvs;
  if (!Array.isArray(layers)) return null;
  return layers.map((layer) =>
    Array.isArray(layer)
      ? layer.map((faceUvs) =>
          Array.isArray(faceUvs)
            ? faceUvs.map((uv) => (uv ? { x: uv.x, y: uv.y } : uv))
            : faceUvs
        )
      : layer
  );
}

function uvBumpRevision(geometry) {
  geometry.__zoidiumUvRevision = (geometry.__zoidiumUvRevision || 0) + 1;
}

function uvApplyToGeometry(geometry) {
  if (!uvIsEligibleGeometry(geometry)) return false;
  const original = uvCloneFaceVertexUvs(geometry);
  if (!original) return false;
  if (!uvNormalizeGeometry(geometry)) {
    // The outline could not be rebuilt (for example a curved path extrusion);
    // remember the decision so the per-frame check stays cheap.
    geometry.__zoidiumUvSkipped = true;
    return false;
  }
  geometry.__zoidiumUvOriginal = original;
  geometry.__zoidiumUvNormalized = true;
  uvBumpRevision(geometry);
  return true;
}

function uvRestoreGeometry(geometry) {
  if (!geometry) return;
  const original = geometry.__zoidiumUvOriginal;
  delete geometry.__zoidiumUvNormalized;
  delete geometry.__zoidiumUvOriginal;
  delete geometry.__zoidiumUvFaceMask;
  if (!original) return;
  const layers = geometry.faceVertexUvs;
  for (let layer = 0; layer < original.length; layer += 1) {
    const source = original[layer];
    const target = layers?.[layer];
    if (!Array.isArray(source) || !Array.isArray(target)) continue;
    for (let face = 0; face < source.length; face += 1) {
      const from = source[face];
      const to = target[face];
      if (!Array.isArray(from) || !Array.isArray(to)) continue;
      for (let index = 0; index < from.length; index += 1) {
        if (from[index] && to[index] && typeof to[index].set === "function") to[index].set(from[index].x, from[index].y);
      }
    }
  }
  if (geometry.uvsNeedUpdate !== undefined) geometry.uvsNeedUpdate = true;
  uvBumpRevision(geometry);
}

// Calls back with each mesh under root and the geometry that holds its UVs: an
// effector's source geometry rather than its working copy.
function uvForEachMesh(root, callback) {
  if (!root) return;
  const visit = (node) => {
    const geometry = node && (node.__zoidiumSourceGeometry || node.geometry);
    if (geometry) callback(node, geometry);
  };
  visit(root);
  if (typeof root.traverse === "function") {
    root.traverse((child) => {
      if (child !== root) visit(child);
    });
  }
}

// A glyph may mix native and Material+ materials. Keep native UVs on each
// face whose material does not use the shared layout. Rebuild only when the
// face mask changes, never on an unchanged frame.
function uvSyncCharacterMesh(mesh, geometry, removed) {
  const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
  let mask = 0;
  for (let i = 0; i < materials.length; i++) {
    if (materials[i] !== removed && materials[i]?.__zoidiumUvLayout) mask |= Array.isArray(mesh.material) ? 1 << i : 3;
  }
  if (!geometry || geometry.__zoidiumUvFaceMask === mask) return;
  uvRestoreGeometry(geometry);
  if (mask && uvApplyToGeometry(geometry)) {
    const original = geometry.__zoidiumUvOriginal[0];
    const target = geometry.faceVertexUvs[0];
    for (let i = 0; i < geometry.faces.length; i++) {
      if (mask & (1 << (geometry.faces[i].materialIndex || 0))) continue;
      for (let j = 0; j < (original[i]?.length || 0); j++) {
        target[i][j].set(original[i][j].x, original[i][j].y);
      }
    }
  }
  geometry.__zoidiumUvFaceMask = mask;
}

function uvHasOtherLayout(mesh, removed) {
  const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
  return materials.some(current => current && current !== removed && current.__zoidiumUvLayout);
}

const uvOwners = new WeakMap();
function uvOwner(material) {
  // A removed material's native parentObject getter dereferences null.
  if ("parent" in material && !material.parent) return null;
  return material.parentObject;
}

// Call from the material's update. Cheap once the geometry is laid out.
function uvEnsureMaterial(material) {
  const owner = uvOwner(material);
  if (!owner) return;
  uvOwners.set(material, owner);
  if (material.threeObj) material.threeObj.__zoidiumUvLayout = true;
  uvForEachMesh(owner.threeObj, (mesh, geometry) => {
    // Slot owners contain unselected Text and ordinary meshes too.
    if (owner.zoidiumTextPlusMode === "character-material" && !mesh.__zoidiumSyncMaterialUvs) return;
    if (mesh.__zoidiumSyncMaterialUvs) {
      uvSyncCharacterMesh(mesh, geometry);
      return;
    }
    uvApplyToGeometry(geometry);
  });
}

// Call from the material's unload. Geometry that a different layout material
// now renders keeps its layout, so switching between Material+ types does not
// flash the native UVs.
function uvReleaseMaterial(material) {
  const owner = uvOwners.get(material) || uvOwner(material);
  uvOwners.delete(material);
  uvForEachMesh(owner?.threeObj, (mesh, geometry) => {
    if (owner?.zoidiumTextPlusMode === "character-material" && !mesh.__zoidiumSyncMaterialUvs) return;
    if (mesh.__zoidiumSyncMaterialUvs) {
      uvSyncCharacterMesh(mesh, geometry, material.threeObj);
      return;
    }
    if (uvHasOtherLayout(mesh, material.threeObj)) return;
    uvRestoreGeometry(geometry);
  });
}

return {
  isEligibleGeometry: uvIsEligibleGeometry,
  normalizeGeometry: uvNormalizeGeometry,
  prepareContours: uvPrepareContours,
  reconstructContours: uvReconstructContours,
  applyToGeometry: uvApplyToGeometry,
  restoreGeometry: uvRestoreGeometry,
  syncCharacterMesh: uvSyncCharacterMesh,
  ensureMaterial: uvEnsureMaterial,
  releaseMaterial: uvReleaseMaterial,
};
};

text./plugins/native-fx/colorcurves.css:
.zoidium-color-curves-control,
.zoidium-color-curves-editor,
.zoidium-color-curves-control * {
  box-sizing: border-box;
  font-family: var(--zui-font);
}

.zoidium-color-curves-control {
  width: 100%;
  min-width: 0;
  color: var(--zui-text);
}

.zoidium-color-curves-editor {
  --zoidium-curve-channel: var(--zui-value);
  width: 100%;
  min-width: 0;
  border: 1px solid var(--zui-border);
  background: var(--zui-border-soft);
}

.zoidium-color-curves-editor[data-channel="red"] {
  --zoidium-curve-channel: #c46f6f;
}

.zoidium-color-curves-editor[data-channel="green"] {
  --zoidium-curve-channel: #6fa47a;
}

.zoidium-color-curves-editor[data-channel="blue"] {
  --zoidium-curve-channel: #718fc4;
}

.zoidium-color-curves-toolbar {
  display: grid;
  grid-template-columns: repeat(4, minmax(28px, 1fr)) auto;
  min-height: 29px;
  border-bottom: 1px solid var(--zui-border);
  background: var(--zui-bg);
}

.zoidium-color-curves-channel,
.zoidium-color-curves-reset {
  min-width: 0;
  height: 28px;
  padding: 0 7px;
  overflow: hidden;
  color: var(--zui-text-muted);
  background: transparent;
  border: 1px solid transparent;
  border-right-color: var(--zui-border);
  outline: 0;
  font-size: var(--zui-font-size-small);
  line-height: 26px;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.zoidium-color-curves-channel:hover,
.zoidium-color-curves-reset:hover {
  color: var(--zui-text-strong);
  background: var(--zui-hover);
}

.zoidium-color-curves-channel:focus-visible,
.zoidium-color-curves-reset:focus-visible {
  border-color: var(--zui-accent);
}

.zoidium-color-curves-channel.is-active {
  color: var(--zui-text-bright);
  background: var(--zui-bg-input);
  border-bottom-color: var(--zoidium-curve-channel);
}

.zoidium-color-curves-reset {
  display: flex;
  align-items: center;
  gap: 4px;
  justify-content: center;
  width: auto;
  padding: 0 6px;
  border-right-color: transparent;
}

.zoidium-color-curves-reset svg {
  width: 13px;
  height: 13px;
  flex: 0 0 auto;
  fill: currentColor;
  pointer-events: none;
}

.zoidium-color-curves-reset span {
  overflow: hidden;
  text-overflow: ellipsis;
}

.zoidium-color-curves-graph {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  overflow: hidden;
  touch-action: none;
  cursor: crosshair;
  background-color: var(--zui-bg-input);
  outline: 0;
}

.zoidium-color-curves-graph:focus-visible {
  box-shadow: inset 0 0 0 1px var(--zui-accent);
}

.zoidium-color-curves-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.zoidium-color-curves-grid {
  fill: none;
  pointer-events: none;
  stroke: color-mix(in srgb, var(--zui-border-soft) 55%, var(--zui-hover));
  stroke-width: 1px;
  vector-effect: non-scaling-stroke;
}

.zoidium-color-curves-grid-center {
  stroke: var(--zui-hover);
}

.zoidium-color-curves-diagonal,
.zoidium-color-curves-reference,
.zoidium-color-curves-active {
  fill: none;
  pointer-events: none;
  vector-effect: non-scaling-stroke;
}

.zoidium-color-curves-diagonal {
  stroke: color-mix(in srgb, var(--zui-hover) 55%, var(--zui-text-faint));
  stroke-width: 1px;
  stroke-dasharray: 3 3;
}

.zoidium-color-curves-reference {
  stroke: var(--zui-text-faint);
  stroke-width: 1px;
  opacity: 0.65;
}

.zoidium-color-curves-active {
  stroke: var(--zoidium-curve-channel);
  stroke-width: 2px;
}

.zoidium-color-curves-point-hit {
  fill: transparent;
  cursor: grab;
}

.zoidium-color-curves-point {
  fill: var(--zui-bg-input);
  stroke: var(--zoidium-curve-channel);
  stroke-width: 2px;
  pointer-events: none;
  vector-effect: non-scaling-stroke;
}

.zoidium-color-curves-point-wrap.is-selected .zoidium-color-curves-point {
  fill: var(--zoidium-curve-channel);
  stroke: var(--zui-text-bright);
}

.zoidium-color-curves-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 24px;
  padding: 3px 6px;
  overflow: hidden;
  color: var(--zui-text-muted);
  background: var(--zui-border-soft);
  border-top: 1px solid var(--zui-border);
  font-size: var(--zui-font-size-compact);
  line-height: 17px;
}

.zoidium-color-curves-status,
.zoidium-color-curves-hint {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.zoidium-color-curves-status {
  color: var(--zoidium-curve-channel);
}

.zoidium-color-curves-hint {
  color: var(--zui-text-faint);
  text-align: right;
}

