/* Shared curve controls stay in CM3's value column, with a square graph. */
.zoidium-color-curves-row > div { min-width: 0; }
.zoidium-color-curves-control { max-width: 100%; white-space: normal; }
.zoidium-color-curves-control .zoidium-color-curves-toolbar { grid-template-columns: repeat(4,minmax(0,1fr)) auto; }
.zoidium-color-curves-control .zoidium-color-curves-channel { padding: 0 3px; }
.zoidium-color-curves-control .zoidium-color-curves-reset { padding: 0 3px; gap: 2px; }
.zoidium-color-curves-control .zoidium-color-curves-reset svg { width: 11px; }
.zoidium-color-curves-control .zoidium-color-curves-graph { aspect-ratio: 1; }
.zoidium-color-curves-control .zoidium-color-curves-footer { flex-wrap: wrap; gap: 0; font-size: 10px; }
.zoidium-color-curves-control .zoidium-color-curves-hint { display: none; }
.zoidium-curve-area { fill: var(--zoidium-curve-channel); opacity: .22; pointer-events: none; }
.zoidium-curve-tangent { fill: none; stroke: var(--zui-text-muted); stroke-width: 1; vector-effect: non-scaling-stroke; pointer-events: none; }
.zoidium-curve-handle { fill: var(--zui-text-muted); stroke: var(--zui-bg-input); stroke-width: 1; vector-effect: non-scaling-stroke; cursor: grab; }
.zoidium-curve-range { position: absolute; left: 4px; font-size: 10px; color: var(--zui-text-muted); pointer-events: none; }
.zoidium-curve-maximum { top: 2px; }.zoidium-curve-minimum { bottom: 2px; }
.zoidium-curve-axis { display: flex; justify-content: space-between; gap: 3px; padding: 2px 4px; font-size: 10px; color: var(--zui-text-muted); }
.zsp-code-toolbar button.proprow { flex: 0 0 auto; width: auto !important; }
.zoidium-curve-axis[hidden] { display: none; }

.zsp-shared-curve .zoidium-color-curves-toolbar { grid-template-columns: minmax(0,1fr) auto; }
.zsp-shared-curve.zsp-curve-rgba .zoidium-color-curves-toolbar { grid-template-columns: repeat(5,minmax(0,1fr)) auto; }
.zoidium-color-curves-control .zoidium-color-curves-reset span { display: none; }
.zoidium-color-curves-control .zoidium-color-curves-channel { font-size: 12px; padding: 0 2px; }
.zoidium-curve-options { display: grid; grid-template-columns: auto minmax(0,1fr); gap: 4px 6px; align-items: center; padding: 5px 2px 2px; font-size: var(--zui-font-size-compact,12px); }
.zoidium-curve-label { color: var(--zui-text-muted); white-space: nowrap; }
.zoidium-curve-options input[type=number] { width: 100%; min-width: 0; box-sizing: border-box; }
.zoidium-curve-select { justify-self: start; max-width: 100%; }
.zoidium-curve-actions { display: flex; align-items: center; gap: 2px; min-width: 0; }
.zoidium-curve-icon { padding: 2px 3px; }
.zoidium-curve-icon svg { width: 17px; height: 17px; fill: #ccc; display: block; }
.zoidium-curve-icon:disabled svg { opacity: .35; }
.zoidium-curve-count { margin-left: auto; color: var(--zui-text-muted); }
.zoidium-curve-options input[type=number]:disabled { background: var(--zui-bg-input); }
.zoidium-curve-options input::placeholder { color: var(--zui-text-faint); }
/* The square graph grows with the value column only up to a fixed size,
   then stays left-aligned so wide sidebars do not enlarge it further. */
.zoidium-color-curves-control,.zsp-shared-curve { max-width: 280px; }
